SELECT * FROM (SELECT CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END AS start_cohort, COUNT(monthly_fee) AS monthly_fee_count FROM subscriptions WHERE customer_id IS NULL GROUP BY CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS t WHERE monthly_fee_count >= 6 ORDER BY monthly_fee_count DESC, start_cohort
